const lessons4=[{n:2,g:3,name:'직접 돌려 보기'},{n:2,g:5,name:'돌리기 전에 예상하기',predict:true},{n:3,g:4,name:'짝꿍 식 찾기'},{n:2,g:4,name:'틀린 짝 고치기',repair:true},{n:3,g:4,name:'책상 위 스티커',life:true},{n:2,g:5,name:'혼자 확인 1',test:true},{n:3,g:2,name:'혼자 확인 2',test:true},{n:4,g:3,name:'혼자 확인 3',test:true}];
let s4={done:false};const d4=()=>lessons4[s4.i];
function start4(){s4={done:s4.done,i:0,score:0};init4()}
function init4(){Object.assign(s4,{phase:'beforeEach',rotated:false,selected:0,row:-1,seen:[],passed:false,retry:false,clean:true,msg:'점 하나를 누르면 테두리로 표시돼요. 돌린 뒤에도 같은 점을 따라가 보세요.'});render4()}
function row4(id){const d=d4();return s4.rotated?id%d.n:Math.floor(id/d.n)}
function board4(){const d=d4(),span=Math.max(d.n,d.g)*44;return `<div class="array-frame" style="width:${span+24}px;height:${span+24}px"><div id="arrayTurn4" class="array-turn" style="width:${span}px;height:${span}px;transform:rotate(${s4.rotated?90:0}deg)">${Array.from({length:d.n*d.g},(_,id)=>`<button class="array-dot ${s4.selected===id?'tracked':''} ${s4.row===row4(id)?'row-lit':''}" style="left:${(span-d.n*44)/2+id%d.n*44}px;top:${(span-d.g*44)/2+Math.floor(id/d.n)*44}px" data-dot4="${id}" aria-label="점 ${id+1}${s4.selected===id?', 선택한 점':''}" aria-pressed="${s4.selected===id}" onclick="select4(${id})"></button>`).join('')}</div></div>`}
function select4(id){s4.selected=id;document.querySelectorAll?.('[data-dot4]').forEach(b=>{b.classList.toggle('tracked',+b.dataset.dot4===id);b.setAttribute('aria-pressed',String(+b.dataset.dot4===id))});s4.msg='테두리가 있는 점을 기억하세요. 돌려도 이 점은 그대로 있어요.';document.querySelector('#feedback4').textContent=s4.msg}
function markRow4(i){s4.row=i;if(!s4.seen.includes(i))s4.seen.push(i);s4.msg=`지금 보는 가로 ${i+1}번째 줄을 표시했어요.`;render4()}
function turn4(){if(s4.phase!=='turn')return;s4.rotated=true;s4.row=-1;s4.seen=[];s4.phase='afterEach';s4.passed=false;s4.msg='같은 점들이 90도 돌아갔어요. 테두리 점이 어디로 갔는지 찾아보세요.';const old=document.querySelector('#arrayTurn4');if(old)old.style.transform='rotate(90deg)';const next=document.querySelector('#turnButton4');if(next)next.disabled=true;setTimeout(()=>{if(view==='stage4'&&s4.phase==='afterEach')render4()},650)}
function choices4(){const d=d4(),p=s4.phase,n=s4.rotated?d.g:d.n,g=s4.rotated?d.n:d.g;if(p.endsWith('Each'))return [1,2,3,4,5].map(v=>[`${v}개씩`,v===n]);if(p.endsWith('Rows'))return [1,2,3,4,5].map(v=>[`${v}줄`,v===g]);if(p.endsWith('Eq')){const a=[`${n} × ${g} = ${n*g}`,true],b=[`${g} × ${n} = ${n*g}`,false];return s4.i%2?[b,a]:[a,b]}if(p==='predict')return [[`${d.n*d.g+1}개`,false],[`${d.n*d.g}개`,true],[`${d.n*d.g-d.n}개`,false]];if(p==='repair')return [['4 × 3 = 12',false],['4 × 2 = 8',true],['2 × 3 = 6',false]];return [['돌리면서 새 점이 생겼기 때문이에요',false],['같은 점들을 돌려 보았기 때문이에요',true],['줄의 수가 언제나 같기 때문이에요',false]]}
function answer4(ok){if(s4.passed)return;const d=d4();if(!ok){s4.clean=false;s4.retry=true;s4.row=0;s4.msg=s4.phase==='reason'||s4.phase==='predict'?'테두리 점을 찾아보세요. 점은 이동했을 뿐 더 생기거나 없어지지 않았어요.':s4.phase.endsWith('Rows')?'가로줄 버튼을 하나씩 누르며 줄의 수를 확인해요.':`강조된 가로 한 줄에 몇 개가 있나요? 앞의 수는 한 줄의 개수, 뒤의 수는 줄의 수예요.`;render4();return}if(s4.retry){s4.retry=false;s4.row=-1;s4.msg='잘 고쳤어요! 줄 힌트를 가렸어요. 같은 질문에 한 번 더 답해 봐요.';render4();return}s4.passed=true;s4.row=-1;s4.msg=s4.phase==='reason'?`같은 ${d.n*d.g}개 점이에요. 묶는 방법이 달라져도 전체 개수는 같아요.`:'그림과 잘 연결했어요!';render4()}
function next4(){if(!s4.passed)return;const d=d4(),p=s4.phase;const order=['beforeEach','beforeRows','beforeEq',...(d.predict?['predict']:[]),'turn','afterEach','afterRows','afterEq',...(d.repair?['repair']:[]),'reason'];const k=order.indexOf(p);if(k===order.length-1){if(d.test&&s4.clean)s4.score++;s4.i++;if(s4.i===lessons4.length){finish4();return}init4();return}s4.phase=order[k+1];s4.seen=[];s4.passed=false;s4.row=-1;s4.retry=false;s4.msg='가로 한 줄의 개수와 줄의 수를 구별해요.';render4()}
function render4(){view='stage4';const d=d4(),p=s4.phase,g=s4.rotated?d.n:d.g;const title=p.endsWith('Each')?'지금 한 줄에 몇 개씩 있나요?':p.endsWith('Rows')?'그런 가로줄이 모두 몇 줄인가요?':p.endsWith('Eq')?'지금 그림에 맞는 식을 붙여요.':p==='turn'?'점 배열 전체를 돌려 보세요.':p==='predict'?`${d.n} × ${d.g} = ${d.n*d.g}. 돌리면 ${d.g} × ${d.n}은 몇 개일까요?`:p==='repair'?'2 × 4 = 8의 짝을 4 × 3 = 12로 붙였어요. 바르게 고쳐요.':'두 식의 답은 왜 같을까요?';app.innerHTML=`<div class="topline"><span class="pill">4단계 · 배열을 돌려 짝꿍 식 찾기</span><span class="small">활동 ${s4.i+1} / 8</span></div><section class="activity"><span class="small">${d.name}</span><h1 class="instruction">${title}</h1>${d.life?'<p>책상에 스티커를 한 줄에 3개씩 4줄 붙였어요. 친구가 옆에서 보면 어떻게 보일까요?</p>':''}<div class="workspace">${board4()}<div class="row-controls" aria-label="가로줄 살펴보기">${Array.from({length:g},(_,i)=>`<button onclick="markRow4(${i})">${i+1}번째 줄</button>`).join('')}</div><p class="small">${p.endsWith('Each')?'먼저 줄 버튼 하나를 눌러 한 줄을 표시한 뒤 답해요.':p.endsWith('Rows')?'줄 버튼을 하나씩 모두 눌러 줄을 확인한 뒤 답해요.':'점을 누르면 같은 점을 따라갈 수 있어요. 줄 버튼을 누르면 가로 한 줄을 표시해요.'}</p>${p==='reason'?`<div class="equation">${d.n} × ${d.g} = ${d.n*d.g}<br>${d.g} × ${d.n} = ${d.n*d.g}</div>`:''}${p==='turn'?'<button id="turnButton4" class="primary" onclick="turn4()">90도 돌리기 ↻</button>':`<div class="choices">${choices4().map(([label,ok])=>`<button onclick="answer4(${ok})" ${s4.passed||(p.endsWith('Each')&&s4.row<0)||(p.endsWith('Rows')&&s4.seen.length<g)?'disabled':''}>${label}</button>`).join('')}</div>`}</div><div id="feedback4" class="feedback ${s4.passed?'good':''}" role="status">${s4.msg}</div><div class="actions"><button onclick="home()">전체 단계</button><button class="primary" onclick="next4()" ${s4.passed?'':'disabled'}>다음으로 →</button></div></section>`}
function finish4(){s4.done=s4.score>=2;view='stage4';s4.finalOpened=false;app.innerHTML=`<section class="activity"><span class="pill">4단계 마무리</span><h1>${s4.done?'짝꿍 식을 찾을 수 있어요!':'같은 점으로 두 식을 만들었어요!'}</h1><p>확인 그림 3개 중 ${s4.score}개에서 두 식과 수의 뜻, 답이 같은 이유를 첫 시도에 연결했어요.${s4.done?' 다음 단계로 나아갈 준비가 되었어요.':' 다시 돌려 보며 연결을 익혀 봐요.'}</p><div class="workspace"><h2>이미 아는 답으로 새 답을 찾아볼까요?</h2><div id="finalArray4">${finalDots4(false)}</div><div class="equation">3 × 4 = 12<br>4 × 3 = □</div><p>아직 돌리지 말고, 답을 먼저 예상해 보세요.</p><div class="choices"><button onclick="finalAnswer4(7)">7</button><button onclick="finalAnswer4(12)">12</button><button onclick="finalAnswer4(16)">16</button></div><div id="finalFeedback4" role="status"></div></div><p class="small">5단계에서는 아는 답으로 새 답을 찾는 방법을 더 알아봐요. 5단계에서 아는 식을 단서로 답을 찾아보세요.</p><div class="actions"><button class="primary" onclick="start5()">5단계로 가기</button><button onclick="start4()">4단계 다시 하기</button><button class="primary" onclick="home()">전체 단계 보기</button></div></section>`}
function finalDots4(rotated){return `<div class="dot-array" style="grid-template-columns:repeat(${rotated?4:3},24px)" aria-label="${rotated?'4개씩 3줄':'3개씩 4줄'}">${Array(12).fill('<span></span>').join('')}</div>`}
function finalAnswer4(n){document.querySelector('#finalFeedback4').innerHTML=n===12?'<p>12개로 예상했어요. 돌려서 확인해 볼까요?</p><button class="primary" onclick="finalTurn4()">돌려서 확인하기 ↻</button>':'<p>3 × 4의 답은 12예요. 같은 점을 돌리면 점이 더 생기거나 없어질까요? 다시 예상해 봐요.</p>'}
function finalTurn4(){document.querySelector('#finalArray4').innerHTML=finalDots4(true);document.querySelector('#finalFeedback4').innerHTML='<p class="feedback good">맞아요! 같은 점 12개예요. 3 × 4 = 12를 알면 4 × 3 = 12도 찾을 수 있어요.</p>'}
